/**
 * TypeScript declaration rendering.
 *
 * Output contains only deterministic data: messages are sorted by key and
 * parameters are sorted by name. No timestamps or environment details are
 * emitted, so generated files can be committed and checked in CI.
 */

import type { AnalyzedMessage } from '../messages/index.js';
import { compareText, contractSignature } from './contract.js';

/**
 * Renders the `MessageArguments` interface for all analyzed messages.
 *
 * Parameterless messages receive `Readonly<Record<string, never>>` instead of
 * `{}`, which would accept any non-nullish value.
 */
export function generateDeclarations(
  messages: ReadonlyMap<string, AnalyzedMessage>,
): string {
  const lines = [...messages]
    .sort(([a], [b]) => compareText(a, b))
    .map(([key, message]) => {
      const contract = message.parameters.length === 0
        ? 'Readonly<Record<string, never>>'
        : `{ ${contractSignature(message.parameters)} }`;

      return `  readonly ${JSON.stringify(key)}: ${contract};`;
    });

  return [
    '// Generated by shareyou-i18n. Do not edit.',
    'export interface MessageArguments {',
    ...lines,
    '}',
    '',
  ].join('\n');
}
